input.command:
$roots = @("$HOME\Desktop\DEV") + (Get-ChildItem "$HOME\Desktop\DEV","$HOME\Desktop\DEV\Football","$HOME\Desktop\DEV\SpecialRequests" -Directory -ErrorAction SilentlyContinue | % FullName) + @("$HOME\.claude","$HOME\.claude\skills","$HOME\.claude\global-memory")
foreach($r in ($roots | Select -Unique)){
  if(-not (Test-Path "$r\.git")){ continue }
  $s = git -C $r status --porcelain 2>$null
  $ab = git -C $r rev-list --left-right --count "HEAD...@{u}" 2>$null
  $br = git -C $r branch --show-current 2>$null
  $ahead = if($ab){ ($ab -split '\s+')[0] } else { 'no-upstream' }
  if($s -or ($ahead -ne '0')){ "{0} [{1}] dirty={2} ahead={3}" -f $r.Replace("$HOME\",''), $br, @($s).Count, $ahead }
}
"--- sweep done"

